-- Blog categories in every language (client, 2026-10-15): the name and description
-- in Spanish, French, Italian and German. A language without an entry shows the English
-- ones. Filled in for the three categories migration 0048 created; editable in Admin -> Blog.
ALTER TABLE "blog_categories" ADD COLUMN "translations" jsonb DEFAULT '{}'::jsonb NOT NULL;
