UPDATE "blog_categories" SET "translations" = '{"es":{"name":"Guías","blurb":"Explicaciones claras y sin tecnicismos de cómo funcionan de verdad los buscadores y los asistentes de inteligencia artificial."},"fr":{"name":"Guides","blurb":"Des explications claires, sans jargon, sur le fonctionnement réel des moteurs de recherche et des assistants d’intelligence artificielle."},"it":{"name":"Guide","blurb":"Spiegazioni chiare e senza gergo tecnico su come funzionano davvero i motori di ricerca e gli assistenti di intelligenza artificiale."},"de":{"name":"Leitfäden","blurb":"Verständliche Erklärungen ohne Fachjargon dazu, wie Suchmaschinen und KI-Assistenten wirklich funktionieren."}}'::jsonb WHERE "slug" = 'guides' AND "translations" = '{}'::jsonb;
